const SKILL_CATEGORY_ICONS = {"monitor":"monitor","server":"server","database":"database","smartphone":"smartphone","check-circle":"circle-check-big","rocket":"rocket","plug":"plug","sparkles":"sparkles","palette":"palette","briefcase":"briefcase"};

function skillSvg(name) {
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('aria-hidden', 'true');
    svg.setAttribute('focusable', 'false');
    svg.innerHTML = SKILL_ICONS[name] || SKILL_ICONS['circle-dot'];
    return svg;
}

function skillFallback(name) {
    const wrap = document.createElement('span');
    wrap.className = 'skill-badge-fallback';
    wrap.appendChild(skillSvg(name));
    return wrap;
}

function createSkillIcon(ref) {
    const sep = ref.indexOf(':');
    const type = ref.slice(0, sep);
    const value = ref.slice(sep + 1);

    // Icône de secours (aucun logo officiel disponible)
    if (type === 'lu') return skillFallback(value);

    // Logo officiel intégré dans le code
    if (type === 'si' || type === 'so' || type === 'dv') {
        const wrap = document.createElement('span');
        wrap.className = 'skill-badge-brand';
        wrap.setAttribute('aria-hidden', 'true');
        wrap.innerHTML = SKILL_BRANDS[ref] || '';
        if (!wrap.firstElementChild) return skillFallback('code-xml');
        return wrap;
    }

    // Logo officiel depuis un fichier : d'abord ton fichier local, puis une adresse distante, puis l'icône de secours
    if (type === 'ur') {
        const [localSrc, remoteSrc, fallbackName] = value.split('|');
        const img = document.createElement('img');
        img.className = 'skill-badge-logo skill-badge-logo--auto';
        img.alt = '';
        img.loading = 'lazy';
        let step = 0;
        img.onerror = () => {
            step++;
            if (step === 1 && remoteSrc) img.src = remoteSrc;
            else img.replaceWith(skillFallback(fallbackName || 'code-xml'));
        };
        img.src = localSrc;
        return img;
    }

    // Logo officiel chargé depuis le CDN, avec icône de secours
    const [slug, fallbackName] = value.split('|');
    const img = document.createElement('img');
    img.className = 'skill-badge-logo';
    img.alt = '';
    img.loading = 'lazy';
    img.src = 'https://cdn.simpleicons.org/' + slug;
    img.onerror = () => img.replaceWith(skillFallback(fallbackName || 'code-xml'));
    return img;
}

function createSkillBadges(items) {
    const badges = document.createElement('div');
    badges.className = 'skill-badges';
    items.forEach(([name, level, iconRef]) => {
        const badge = document.createElement('span');
        badge.className = 'skill-badge ' + level;
        badge.title = level === 'mastered' ? 'Maîtrisé' : 'Notions';
        badge.appendChild(createSkillIcon(iconRef));
        const label = document.createElement('span');
        label.className = 'skill-badge-label';
        label.textContent = name;
        badge.appendChild(label);
        badges.appendChild(badge);
    });
    return badges;
}

function renderSkills() {
    const grid = document.getElementById('skillsGrid');
    if (!grid) return;
    grid.innerHTML = '';

    if (!document.getElementById('skillsLegend')) {
        const legend = document.createElement('div');
        legend.id = 'skillsLegend';
        legend.className = 'skills-legend';
        legend.innerHTML = '<span><i class="legend-dot mastered"></i>Maîtrisé</span><span><i class="legend-dot notions"></i>Notions</span>';
        grid.parentNode.insertBefore(legend, grid);
    }

    skills.forEach((category, index) => {
        const card = document.createElement('article');
        card.className = 'skill-category';
        card.style.setProperty('--skill-card-index', index);

        const header = document.createElement('div');
        header.className = 'skill-category-header';

        const icon = document.createElement('span');
        icon.className = 'skill-category-icon';
        icon.appendChild(skillSvg(SKILL_CATEGORY_ICONS[category.icon] || 'monitor'));

        const heading = document.createElement('div');
        heading.className = 'skill-category-heading';
        const title = document.createElement('h3');
        title.className = 'skill-category-title';
        title.textContent = category.category;
        const description = document.createElement('p');
        description.className = 'skill-category-description';
        description.textContent = category.description || '';
        heading.append(title, description);

        header.append(icon, heading);
        card.appendChild(header);

        if (category.skills) card.appendChild(createSkillBadges(category.skills));
        if (category.groups) {
            category.groups.forEach(group => {
                const groupTitle = document.createElement('h4');
                groupTitle.className = 'skill-group-title';
                groupTitle.textContent = group.title;
                card.appendChild(groupTitle);
                card.appendChild(createSkillBadges(group.skills));
            });
        }
        grid.appendChild(card);
    });
}

renderSkills();

// ========== Animation des catégories de compétences ==========
const skillCategories = document.querySelectorAll('.skill-category');
if ('IntersectionObserver' in window) {
    const skillObserver = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('visible');
                observer.unobserve(entry.target);
            }
        });
    }, { threshold: 0.08 });
    skillCategories.forEach(category => skillObserver.observe(category));
} else {
    skillCategories.forEach(category => category.classList.add('visible'));
}

// ========== Formulaire avec EmailJS ==========
document.getElementById('contactForm')?.addEventListener('submit', function(e) {
    e.preventDefault();
    
    const submitBtn = document.getElementById('submitBtn');
    const originalText = submitBtn.textContent;
    
    submitBtn.disabled = true;
    submitBtn.textContent = 'Envoi en cours...';
    
    emailjs.sendForm(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, this)
        .then(function(response) {
            console.log('SUCCESS!', response.status, response.text);
            document.getElementById('contactForm').reset();
            showSuccessModal();
        }, function(error) {
            console.log('FAILED...', error);
            alert("❌ Erreur lors de l'envoi. Veuillez réessayer.");
        })
        .finally(function() {
            submitBtn.disabled = false;
            submitBtn.textContent = originalText;
        });
});

// ========== Modal de Succès ==========
function showSuccessModal() {
    const modal = document.getElementById('successModal');
    if (modal) {
        modal.classList.add('active');
        document.body.style.overflow = 'hidden';
    }
}

function closeSuccessModal() {
    const modal = document.getElementById('successModal');
    if (modal) {
        modal.classList.remove('active');
        document.body.style.overflow = 'auto';
    }
}

document.getElementById('successModal')?.addEventListener('click', function(e) {
    if (e.target.id === 'successModal') {
        closeSuccessModal();
    }
});

// ========== Scroll to Top ==========
const scrollTop = document.getElementById('scrollTop');

window.addEventListener('scroll', () => {
    if (!scrollTop) return;
    if (window.pageYOffset > 300) {
        scrollTop.classList.add('visible');
    } else {
        scrollTop.classList.remove('visible');
    }
});

scrollTop?.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
});

// ========== PWA SERVICE WORKER ==========
if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
        navigator.serviceWorker.register('sw.js')
            .then(registration => {
                console.log('Service Worker enregistré avec succès:', registration.scope);
            })
            .catch(error => {
                console.log("Échec de l'enregistrement du Service Worker:", error);
            });
    });
}